cd "$ARCHON_HORIZON_ROOT/.archon-horizon/runs/0047/sessions"; for d in 0004 0006 0008 0010; do f=$d-horizon-ajcr-w4-rep-free/transcript.jsonl; echo "=== $f  lines=$(wc -l < $f) size=$(du -h $f | cut -f1)"; python3 -c "
import json
lines=open('$f').read().splitlines()
# print last few assistant text messages
out=[]
for l in lines:
    try: r=json.loads(l)
    except: continue
    t=r.get('type')
    if t=='assistant':
        for c in r.get('message',{}).get('content',[]):
            if c.get('type')=='text' and c.get('text','').strip(): out.append(('TXT',c['text'][:400]))
            elif c.get('type')=='tool_use': out.append(('TOOL',str(c.get('name'))+' '+json.dumps(c.get('input'))[:200]))
    elif t=='result':
        out.append(('RESULT', json.dumps(r)[:400]))
for k,v in out[-8:]: print(k,':',v)
"; done

